'use client'

// Generated by SpecForge from "Shop" (1.0.0). Safe to edit.
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { useApi } from '@/lib/api/api-provider'
import type { Page } from '@/lib/api/types'
import type { Country, CountryInput } from './types'

const PATH = '/api/shop/countries'
const KEY = ['shop', 'country'] as const

export interface CountryFilters {
  q?: string
  page?: number
  size?: number
  sort?: string
}

const item = (id: string) => `${PATH}/${encodeURIComponent(String(id))}`

export function useCountryList(filters: CountryFilters) {
  const api = useApi()
  return useQuery({
    queryKey: [...KEY, filters],
    queryFn: () => api.get<Page<Country>>(PATH, { ...filters }),
    placeholderData: previous => previous,
  })
}

export function useSaveCountry() {
  const api = useApi()
  const queryClient = useQueryClient()
  return useMutation({
    mutationFn: ({ id, input }: { id?: string; input: CountryInput }) =>
      id != null ? api.put<Country>(item(id), input) : api.post<Country>(PATH, input),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['shop'] }),
  })
}

export function useDeleteCountry() {
  const api = useApi()
  const queryClient = useQueryClient()
  return useMutation({
    mutationFn: (id: string) => api.delete(item(id)),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['shop'] }),
  })
}
